# Producer: inside the web request, fast
def upload_video(request):
    video_id = storage.save(request.file)
    queue.publish("transcode",
                  {"video_id": video_id})
    return {"status": "processing"}

# Consumer: a separate worker process
def worker():
    while True:
        msg = queue.receive("transcode")
        vid = msg["video_id"]
        # idempotent: skip repeats
        if not already_done(vid):
            transcode(vid)
            mark_done(vid)
        queue.ack(msg)   # only now removed

